import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import SummaryStep from '../CraracterSheet/SummaryStep';// 4. Sayfada yaptığımız efsanevi özet sayfası
import './GMDashboard.css';

const GMDashboard = () => {
    const navigate = useNavigate();
    const logEndRef = useRef(null);

    // --- MENÜ STATE'LERİ ---
    const [isTopOpen, setIsTopOpen] = useState(true);
    const [isBottomOpen, setIsBottomOpen] = useState(false);

    // --- OYUN & ZAR STATE'LERİ ---
    const gameCode = "EPIC2026";
    const [logs, setLogs] = useState([{ id: 1, text: "Campaign Started. Waiting for players...", isHidden: false }]);
    const [diceQty, setDiceQty] = useState(1);
    const [diceType, setDiceType] = useState(20);
    const [isHiddenRoll, setIsHiddenRoll] = useState(false);

    // --- OYUNCU (MOCK DATA) ---
    // Gerçekte bu veriler Firebase/MongoDB'den canlı (socket) olarak gelecek
    const [players, setPlayers] = useState([
        {
            id: 'p1',
            name: 'Elandor', charClass: 'Rogue', level: 4, species: 'Elf', playerName: 'Ahmet',
            stats: { Strength: 10, Dexterity: 18, Constitution: 12, Intelligence: 14, Wisdom: 10, Charisma: 14 },
            proficiencies: { 'Dexterity-Stealth': true, 'Dexterity-Acrobatics': true },
            armorClass: 15, currentHp: 28, maxHp: 32, speed: 30,
            weapons: [{ id: 1, name: 'Rapier', damageDice: '1d8' }],
            spellSlots: { 1: { max: 0, used: 0 } }, spells: [],
            currency: { cp: 0, sp: 5, ep: 0, gp: 120, pp: 0 }, inventory: [],
            traits: { personality: 'Always hides in shadows.' }, portrait: null
        },
        {
            id: 'p2',
            name: 'Thorgal', charClass: 'Barbarian', level: 4, species: 'Orc', playerName: 'Can',
            stats: { Strength: 20, Dexterity: 14, Constitution: 16, Intelligence: 8, Wisdom: 10, Charisma: 10 },
            proficiencies: { 'Strength-Athletics': true },
            armorClass: 16, currentHp: 45, maxHp: 45, speed: 40,
            weapons: [{ id: 1, name: 'Greataxe', damageDice: '1d12' }],
            spellSlots: { 1: { max: 0, used: 0 } }, spells: [],
            currency: { cp: 0, sp: 0, ep: 0, gp: 10, pp: 0 }, inventory: [],
            traits: { personality: 'SMASH!' }, portrait: null
        }
    ]);

    const [selectedPlayer, setSelectedPlayer] = useState(null);

    // Modifiye hesaplayıcı (SummaryStep'in çökmemesi için gerekli)
    const calculateModifier = (score) => Math.floor((score - 10) / 2);

    // Her yeni log eklendiğinde log penceresini en alta kaydır
    useEffect(() => {
        logEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [logs]);

    // --- HANDLERS ---
    const handleCopyCode = () => {
        navigator.clipboard.writeText(gameCode);
        addLog(`Game Code '${gameCode}' copied to clipboard.`, true);
    };

    const addLog = (text, isHidden = false) => {
        setLogs(prev => [...prev, { id: Date.now(), text, isHidden }]);
    };

    const handleLongRest = () => {
        if(window.confirm("Are you sure? This will restore all HP and Spell Slots for ALL players!")) {
            addLog("The party takes a Long Rest. HP & Spells restored.", false);
            // İleride burada tüm oyuncuların HP'sini maxHp'ye eşitleyeceğiz
        }
    };

    const handleRollDice = () => {
        let total = 0;
        let rolls = [];
        for(let i = 0; i < diceQty; i++) {
            let roll = Math.floor(Math.random() * diceType) + 1;
            rolls.push(roll);
            total += roll;
        }

        const logMsg = `GM Rolled ${diceQty}d${diceType} 🎲 [${rolls.join(', ')}] = Total: ${total}`;
        addLog(logMsg, isHiddenRoll);
    };

    return (
        <div className="gm-dashboard-wrapper">

            {/* --- TOP MENU (Collapsible) --- */}
            <div className={`gm-top-menu ${isTopOpen ? 'open' : 'closed'}`}>
                <div className="top-menu-content">
                    <div className="top-left">
                        <button className="exit-btn" onClick={() => navigate('/host-game')}>🚪 EXIT</button>
                        <div className="game-code-box" onClick={handleCopyCode} title="Click to Copy">
                            JOIN CODE: <span className="highlight-code">{gameCode}</span>
                        </div>
                        <div className="player-count-badge">👥 Players: {players.length}</div>
                    </div>

                    <div className="top-right">
                        <button className="action-btn combat-btn" onClick={() => addLog("⚔️ COMBAT INITIATED!", false)}>
                            START COMBAT
                        </button>
                        <button className="action-btn rest-btn" onClick={handleLongRest}>
                            🏕️ LONG REST
                        </button>
                    </div>
                </div>
                {/* Kapatıp Açma Kulpu */}
                <div className="menu-handle top-handle" onClick={() => setIsTopOpen(!isTopOpen)}>
                    {isTopOpen ? '▲' : '▼'}
                </div>
            </div>

            {/* --- MIDDLE AREA --- */}
            <div className="gm-middle-area">

                {/* Sol Taraf: Oyuncu Listesi */}
                <div className="gm-sidebar">
                    <h3 className="sidebar-title">PARTY MEMBERS</h3>
                    <div className="player-list">
                        {players.map(p => (
                            <div 
                                key={p.id} 
                                className={`player-card ${selectedPlayer?.id === p.id ? 'active' : ''}`}
                                onClick={() => setSelectedPlayer(p)}
                            >
                                <div className="p-card-header">
                                    <strong>{p.name}</strong>
                                    <span className="p-hp-tag">HP: {p.currentHp}/{p.maxHp}</span>
                                </div>
                                <div className="p-card-sub">Lvl {p.level} {p.charClass}</div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Orta Taraf: Seçili Karakterin Özeti */}
                <div className="gm-main-content">
                    {selectedPlayer ? (
                        <div className="summary-wrapper fade-in">
                            <SummaryStep character={selectedPlayer} calculateModifier={calculateModifier} />
                        </div>
                    ) : (
                        <div className="placeholder-msg">
                            <div className="placeholder-icon">👁️</div>
                            <h2>SELECT A PLAYER</h2>
                            <p>Click on a character card to view their full sheet.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* --- BOTTOM RIGHT HUD (Dice & Logs - Her zaman görünür) --- */}
            <div className="gm-hud-container">

                {/* Zar Bölümü */}
                <div className="dice-panel">
                    <div className="dice-controls">
                        <input type="number" min="1" max="99" value={diceQty} onChange={(e) => setDiceQty(e.target.value)} />
                        <span>d</span>
                        <select value={diceType} onChange={(e) => setDiceType(e.target.value)}>
                            <option value={4}>4</option><option value={6}>6</option>
                            <option value={8}>8</option><option value={10}>10</option>
                            <option value={12}>12</option><option value={20}>20</option>
                            <option value={100}>100</option>
                        </select>
                    </div>

                    <div className="dice-actions">
                        <label className="hidden-roll-toggle">
                            <input type="checkbox" checked={isHiddenRoll} onChange={(e) => setIsHiddenRoll(e.target.checked)} />
                            <span className="toggle-label">Hidden (GM Only)</span>
                        </label>
                        <button className="roll-btn" onClick={handleRollDice}>ROLL 🎲</button>
                    </div>
                </div>

                {/* Log (Kayıt) Bölümü */}
                <div className="log-panel">
                    <div className="log-header">COMBAT & EVENT LOG</div>
                    <div className="log-messages">
                        {logs.map(log => (
                            <div key={log.id} className={`log-entry ${log.isHidden ? 'hidden-log' : 'public-log'}`}>
                                {log.isHidden && <span className="hidden-icon" title="Hidden from players">👁️‍🗨️</span>}
                                {log.text}
                            </div>
                        ))}
                        <div ref={logEndRef} /> {/* Otomatik kaydırma için hedef */}
                    </div>
                </div>
            </div>

            {/* --- BOTTOM MENU (Collapsible) --- */}
            <div className={`gm-bottom-menu ${isBottomOpen ? 'open' : 'closed'}`}>
                {/* Kapatıp Açma Kulpu */}
                <div className="menu-handle bottom-handle" onClick={() => setIsBottomOpen(!isBottomOpen)}>
                    {isBottomOpen ? '▼' : '▲'} MENU
                </div>
                <div className="bottom-menu-content">
                    <h3 style={{color: '#d4af37', margin: 0}}>Expanded Tools Coming Soon...</h3>
                    {/* Buraya npc jeneratör, harita araçları eklenebilir */}
                </div>
            </div>

        </div>
    );
};

export default GMDashboard;
